// ============================================================================
// LIOR KUROGANE - LÓGICA DE APLICACIÓN Y CONEXIÓN A SUPABASE (app.js)
// ============================================================================

const SUPABASE_URL = 'https://giodidtjkswxuzmvpinz.supabase.co';
const SUPABASE_KEY = 'sb_publishable_8q_t7S9FhDOuEiuh95k5EQ_krnGZPe0';
const supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);

// Icono exacto del Pourcoon proporcionado por ti (con fondo transparente optimizado para sello en modo oscuro)
const POURCOON_STAMP_DATA_URI = 'data:image/png;base64,';

let character = null;
let inventory = [];
let spells = [];
let companions = [];
let logs = [];

// Configurar logo en el header con respaldo al Data URI por si se abre sin servidor
document.addEventListener('DOMContentLoaded', () => {
  const headerLogo = document.getElementById('headerLogoImg');
  if (headerLogo) {
    headerLogo.onerror = () => { headerLogo.src = POURCOON_STAMP_DATA_URI; };
  }
  initApp();
});

// Progresión oficial de Brujo 5e del Nivel 1 al 20
function getWarlockProgression(level) {
  const lvl = Number(level) || 6;
  const prof = Math.ceil(lvl / 4) + 1;
  const slotLevel = Math.min(5, Math.ceil(lvl / 2));
  const slotCount = lvl === 1 ? 1 : (lvl < 11 ? 2 : (lvl < 17 ? 3 : 4));
  const smiteDice = `${1 + slotLevel}d8`;
  const eldritchBeams = lvl < 5 ? 1 : (lvl < 11 ? 2 : (lvl < 17 ? 3 : 4));
  return { prof, slotLevel, slotCount, smiteDice, eldritchBeams };
}

function getMod(score) {
  return Math.floor((Number(score) - 10) / 2);
}

// ============================================================================
// 1. INICIALIZACIÓN Y CARGA DESDE SUPABASE
// ============================================================================
async function initApp() {
  const select = document.getElementById('levelSelect');
  if (select && select.options.length === 0) {
    select.innerHTML = Array.from({ length: 20 }, (_, i) => `<option value="${i + 1}">${i + 1}</option>`).join('');
  }

  try {
    const { data: chars, error } = await supabaseClient.from('characters').select('*').limit(1);
    if (error) throw error;

    if (!chars || chars.length === 0) {
      setSyncBadge('Ejecuta el nuevo script SQL en Supabase', false);
      return;
    }

    character = chars[0];
    const [invRes, spRes, compRes, logRes] = await Promise.all([
      supabaseClient.from('character_inventory').select('*').eq('character_id', character.id).order('is_favorite_pact', { ascending: false }).order('name'),
      supabaseClient.from('character_spells').select('*').eq('character_id', character.id).order('level').order('name'),
      supabaseClient.from('character_companions').select('*').eq('character_id', character.id).order('is_summoned', { ascending: false }).order('name'),
      supabaseClient.from('combat_logs').select('*').eq('character_id', character.id).order('created_at', { ascending: false }).limit(30)
    ]);

    inventory = invRes.data || [];
    spells = spRes.data || [];
    companions = compRes.data || [];
    logs = logRes.data || [];

    // Asegurar que exista un arma de pacto activa seleccionada
    if (!character.active_pact_weapon_id) {
      const fav = inventory.find(i => i.is_favorite_pact) || inventory.find(i => i.is_pact_weapon);
      if (fav) character.active_pact_weapon_id = fav.id;
    }

    setSyncBadge('Sincronizado con Supabase', true);
    renderAll();
  } catch (err) {
    console.error('Error conectando con Supabase:', err);
    setSyncBadge('Error de conexión / Verifica el SQL en Supabase', false);
  }
  lucide.createIcons();
}

function setSyncBadge(text, ok = true) {
  const el = document.getElementById('syncStatus');
  if (!el) return;
  el.className = `text-xs flex items-center gap-1.5 font-medium shrink-0 ${ok ? 'text-emerald-400' : 'text-amber-400'}`;
  el.innerHTML = `<span class="w-2 h-2 rounded-full ${ok ? 'bg-emerald-400 animate-pulse' : 'bg-amber-400'}"></span> ${text}`;
}

// ============================================================================
// 2. RENDERIZADO GENERAL Y CÁLCULOS AUTOMÁTICOS
// ============================================================================
function renderAll() {
  if (!character) return;
  const prog = getWarlockProgression(character.level);
  const chaMod = getMod(character.cha);
  const spellSaveDC = 8 + prog.prof + chaMod;
  const spellAttackBonus = prog.prof + chaMod;

  // HUD Superior
  document.getElementById('charNameInput').value = character.name || 'Lior Kurogane';
  document.getElementById('levelSelect').value = character.level;
  document.getElementById('profBadge').textContent = `Comp. +${prog.prof}`;
  document.getElementById('hpCurrent').value = character.hp_current;
  document.getElementById('hpMax').value = character.hp_max;
  document.getElementById('hpTemp').value = character.hp_temp;

  // Munición en Combate
  document.getElementById('ammoPistolInput').value = character.ammo_pistol ?? 20;
  document.getElementById('ammoMusketInput').value = character.ammo_musket ?? 20;

  // Cálculo automático de Clase de Armadura (Armadura equipada + Escudo equipado + Escudo de Reacción)
  let calcAC = 10 + getMod(character.dex);
  const equippedArmor = inventory.find(i => i.is_equipped && i.category === 'armadura');
  if (equippedArmor && equippedArmor.ac_bonus > 0) calcAC = Number(equippedArmor.ac_bonus);
  const equippedShield = inventory.find(i => i.is_equipped && i.category === 'escudo');
  if (equippedShield) calcAC += Number(equippedShield.ac_bonus || 2);
  if (character.combat_state?.shield_active) calcAC += 5;
  document.getElementById('acDisplay').textContent = calcAC;

  // Espacios de Magia del Pacto
  document.getElementById('pactSlotLabel').textContent = `Espacios (Nvl ${prog.slotLevel})`;
  const slotsDiv = document.getElementById('pactSlotsContainer');
  slotsDiv.innerHTML = '';
  for (let i = 0; i < prog.slotCount; i++) {
    const isUsed = i < (character.spell_slots_used || 0);
    const btn = document.createElement('button');
    btn.className = `w-6 h-6 rounded-md border transition flex items-center justify-center text-xs font-bold ${
      isUsed
        ? 'bg-slate-900 border-slate-700 text-slate-600'
        : 'bg-purple-600 border-purple-400 text-white shadow-sm shadow-purple-500/50'
    }`;
    btn.innerHTML = isUsed ? '✕' : '◆';
    btn.onclick = () => toggleSpellSlot(i);
    slotsDiv.appendChild(btn);
  }

  // Escalado por nivel en botones de combate
  document.getElementById('smiteDiceBtn').textContent = prog.smiteDice;
  document.getElementById('spellSaveBadge').textContent = `CD ${spellSaveDC} | Ataque +${spellAttackBonus}`;
  document.getElementById('hexcurseDesc').textContent = `+${prog.prof} daño por impacto, Crítico 19-20, Cura ${character.level + chaMod} PG al morir.`;
  document.getElementById('shroudDesc').textContent = `Asusta a 10 pies (CD ${spellSaveDC}) y suma +${character.level} daño necrótico 1 vez/turno.`;
  document.getElementById('btnHealingHands').textContent = `Manos Curativas (+${character.level} PG)`;

  renderActionEconomy();
  renderStampCard();
  renderPactWeaponSelectorAndCard(prog, chaMod);
  renderSecondaryWeapons(prog, chaMod);
  renderStatsGrid(prog);
  renderCombatSpells(prog, spellSaveDC, spellAttackBonus);
  renderCombatCompanions(prog, chaMod);
  renderCombatLogs();
  renderInventoryTab();
  renderSpellsTab();
  renderCompanionsTab();
  lucide.createIcons();
}

// ============================================================================
// 3. SELECTOR DE ARMA DEL PACTO (4 FAVORITAS + RESTO DEL ARSENAL) Y MUNICIÓN
// ============================================================================
function renderPactWeaponSelectorAndCard(prog, chaMod) {
  const select = document.getElementById('pactWeaponSelector');
  const quickBar = document.getElementById('favoritePactQuickBar');
  const card = document.getElementById('activePactWeaponCard');

  const favorites = inventory.filter(i => i.category === 'arma' && i.is_favorite_pact);
  const otherPactWeapons = inventory.filter(i => i.category === 'arma' && !i.is_favorite_pact && i.is_pact_weapon);

  // Construir menú desplegable con optgroups
  let htmlOptions = '';
  if (favorites.length > 0) {
    htmlOptions += `<optgroup label="★ Tus 4 Armas Favoritas del Pacto">`;
    favorites.forEach(w => {
      const sel = w.id === character.active_pact_weapon_id ? 'selected' : '';
      htmlOptions += `<option value="${w.id}" ${sel}>★ ${w.name} (${w.damage_dice} ${w.damage_type || ''} • ${w.range_info || ''})</option>`;
    });
    htmlOptions += `</optgroup>`;
  }

  if (otherPactWeapons.length > 0) {
    htmlOptions += `<optgroup label="⚔ Otras Formas de Armas Invocables (Compendio 5e)">`;
    otherPactWeapons.forEach(w => {
      const sel = w.id === character.active_pact_weapon_id ? 'selected' : '';
      htmlOptions += `<option value="${w.id}" ${sel}>${w.name} (${w.damage_dice} ${w.damage_type || ''} • ${w.range_info || ''})</option>`;
    });
    htmlOptions += `</optgroup>`;
  }

  select.innerHTML = htmlOptions;

  // Botones rápidos para tus Favoritas
  quickBar.innerHTML = favorites.map(w => {
    const isActive = w.id === character.active_pact_weapon_id;
    const shortName = w.name.replace(' del Pacto', '');
    return `
      <button onclick="changeActivePactWeapon('${w.id}')" class="px-2.5 py-1.5 rounded-lg text-xs font-bold border transition truncate ${
        isActive
          ? 'bg-purple-700 border-purple-400 text-white shadow'
          : 'bg-slate-900 border-slate-700 text-slate-300 hover:border-purple-500'
      }">
        ★ ${shortName}
      </button>
    `;
  }).join('');

  // Tarjeta de ataque del Arma del Pacto actualmente invocada
  const activeWeapon = inventory.find(i => i.id === character.active_pact_weapon_id) || favorites[0] || otherPactWeapons[0];
  if (!activeWeapon) {
    card.innerHTML = `<div class="text-xs text-slate-400">Selecciona o marca un arma como Arma del Pacto en la Pestaña 2.</div>`;
    return;
  }

  const cs = character.combat_state || {};
  const hexBonus = cs.hexblade_curse ? prog.prof : 0;
  const shroudBonus = cs.necrotic_shroud_active ? character.level : 0;
  const hexSpellActive = cs.concentration_spell && cs.concentration_spell.toLowerCase().includes('maleficio');

  const magicMod = Number(activeWeapon.magic_bonus) || 1;
  const toHit = prog.prof + chaMod + magicMod;
  const flatDmg = chaMod + magicMod + hexBonus;

  let extraTags = [];
  if (hexBonus > 0) extraTags.push(`+${hexBonus} Maldición (Crítico 19-20)`);
  if (hexSpellActive) extraTags.push(`+1d6 Necrótico (Maleficio)`);
  if (shroudBonus > 0) extraTags.push(`+${shroudBonus} Necrótico (Mortaja 1/turno)`);

  // Detectar si usa munición de pistola o mosquete
  const nameLower = activeWeapon.name.toLowerCase();
  const isPistol = nameLower.includes('pistola') || activeWeapon.ammo_type === 'balas_pistola';
  const isMusket = nameLower.includes('mosquete') || nameLower.includes('trabuco') || nameLower.includes('rifle') || activeWeapon.ammo_type === 'balas_mosquete';
  let ammoBadge = '';
  if (isPistol) {
    ammoBadge = `<span class="text-xs font-bold px-2 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-700">Balas Pistola: ${character.ammo_pistol ?? 20}</span>`;
  } else if (isMusket) {
    ammoBadge = `<span class="text-xs font-bold px-2 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-700">Balas Mosquete: ${character.ammo_musket ?? 20}</span>`;
  }

  card.innerHTML = `
    <div class="flex flex-wrap items-start justify-between gap-2">
      <div>
        <div class="flex items-center gap-2">
          <span class="text-base font-black text-white">${activeWeapon.name}</span>
          ${ammoBadge}
        </div>
        <div class="text-xs text-slate-400 mt-0.5">${activeWeapon.range_info || ''} • ${activeWeapon.properties || ''}</div>
      </div>
      <div class="text-right">
        <div class="text-xs font-extrabold text-amber-400">Impacto: +${toHit} (Carisma + Bono Pacto)</div>
        <div class="text-base font-black text-emerald-400">${activeWeapon.damage_dice} + ${flatDmg} <span class="text-xs font-normal text-slate-300">${activeWeapon.damage_type || ''}</span></div>
      </div>
    </div>

    ${extraTags.length > 0 ? `
      <div class="mt-2.5 text-xs text-purple-200 bg-purple-950/60 px-3 py-1.5 rounded-lg border border-purple-700/60">
        Dados adicionales activos en tu tirada: <strong>${extraTags.join(' | ')}</strong>
      </div>
    ` : ''}

    <div class="grid grid-cols-2 gap-2.5 mt-3 pt-2.5 border-t border-slate-800">
      <button onclick="fireOrStrikePactWeapon('${activeWeapon.id}', 1, '+${toHit}', '${activeWeapon.damage_dice}+${flatDmg}')" class="py-2 px-3 rounded-xl bg-purple-700 hover:bg-purple-600 text-white text-xs font-bold transition shadow flex items-center justify-center gap-1.5">
        1° Ataque ${isPistol || isMusket ? '(Disparar -1 Bala)' : '(Golpear)'}
      </button>
      <button onclick="fireOrStrikePactWeapon('${activeWeapon.id}', 2, '+${toHit}', '${activeWeapon.damage_dice}+${flatDmg}')" class="py-2 px-3 rounded-xl bg-indigo-700 hover:bg-indigo-600 text-white text-xs font-bold transition shadow flex items-center justify-center gap-1.5">
        2° Ataque (Filo Sediento)
      </button>
    </div>
  `;
}

async function changeActivePactWeapon(weaponId) {
  character.active_pact_weapon_id = weaponId;
  const w = inventory.find(i => i.id === weaponId);
  renderAll();
  if (w) {
    await addCombatLog(`Invocó forma del Pacto del Filo: ${w.name}.`);
  }
  await supabaseClient.from('characters').update({ active_pact_weapon_id: weaponId }).eq('id', character.id);
}

async function fireOrStrikePactWeapon(weaponId, attackNum, hitBonus, dmgFormula) {
  const w = inventory.find(i => i.id === weaponId);
  if (!w) return;

  const nameLower = w.name.toLowerCase();
  const isPistol = nameLower.includes('pistola') || w.ammo_type === 'balas_pistola';
  const isMusket = nameLower.includes('mosquete') || nameLower.includes('trabuco') || nameLower.includes('rifle') || w.ammo_type === 'balas_mosquete';

  if (isPistol) {
    if ((character.ammo_pistol ?? 0) <= 0) {
      alert('¡Sin balas de Pistola! Recarga o cambia de forma tu Arma del Pacto.');
      return;
    }
    character.ammo_pistol = Math.max(0, (character.ammo_pistol ?? 20) - 1);
  } else if (isMusket) {
    if ((character.ammo_musket ?? 0) <= 0) {
      alert('¡Sin balas de Mosquete! Recarga o cambia de forma tu Arma del Pacto.');
      return;
    }
    character.ammo_musket = Math.max(0, (character.ammo_musket ?? 20) - 1);
  }

  character.combat_state.action_used = true;
  const ammoNote = isPistol ? ` [Quedan ${character.ammo_pistol} balas de pistola]` : (isMusket ? ` [Quedan ${character.ammo_musket} balas de mosquete]` : '');
  await addCombatLog(`Ataque #${attackNum} con ${w.name} (${hitBonus} a impactar | Daño: ${dmgFormula} ${w.damage_type || ''})${ammoNote}.`);
  await saveCharacterCore();
}

async function adjustAmmo(type, delta) {
  if (type === 'pistol') {
    character.ammo_pistol = Math.max(0, (Number(character.ammo_pistol) || 0) + delta);
  } else {
    character.ammo_musket = Math.max(0, (Number(character.ammo_musket) || 0) + delta);
  }
  renderAll();
  await supabaseClient.from('characters').update({
    ammo_pistol: character.ammo_pistol,
    ammo_musket: character.ammo_musket
  }).eq('id', character.id);
}

async function saveAmmoManual() {
  character.ammo_pistol = Math.max(0, Number(document.getElementById('ammoPistolInput').value) || 0);
  character.ammo_musket = Math.max(0, Number(document.getElementById('ammoMusketInput').value) || 0);
  renderAll();
  await supabaseClient.from('characters').update({
    ammo_pistol: character.ammo_pistol,
    ammo_musket: character.ammo_musket
  }).eq('id', character.id);
}

// Armas secundarias equipadas que no son el arma de pacto activa (ej. Daga)
function renderSecondaryWeapons(prog, chaMod) {
  const container = document.getElementById('secondaryWeaponsList');
  const sec = inventory.filter(i => i.is_equipped && i.category === 'arma' && !i.is_pact_weapon);

  if (sec.length === 0) {
    container.innerHTML = `<div class="text-xs text-slate-500">Ninguna arma secundaria física marcada como equipada.</div>`;
    return;
  }

  container.innerHTML = sec.map(w => {
    const mod = Math.max(getMod(character.str), getMod(character.dex));
    const toHit = prog.prof + mod + (Number(w.magic_bonus) || 0);
    const dmg = mod + (Number(w.magic_bonus) || 0);
    return `
      <div class="bg-panel border border-slate-800 rounded-xl p-3 flex items-center justify-between">
        <div>
          <div class="font-bold text-xs text-white">${w.name} <span class="text-[10px] text-slate-400">(${w.range_info || ''})</span></div>
          <div class="text-[11px] text-emerald-400 font-semibold">Impacto +${toHit} • Daño ${w.damage_dice}+${dmg} ${w.damage_type || ''}</div>
        </div>
        <button onclick="addCombatLog('Ataque secundario con ${w.name} (+${toHit} | ${w.damage_dice}+${dmg}).')" class="px-3 py-1 rounded-lg bg-slate-800 hover:bg-purple-700 text-xs font-bold text-white">
          Usar
        </button>
      </div>
    `;
  }).join('');
}

// ============================================================================
// 4. TARJETA DE LOS 10 SELLOS DEL POURCOON CON TU ICONO REAL
// ============================================================================
function renderStampCard() {
  let stamps = character.death_stamps;
  if (!Array.isArray(stamps) || stamps.length !== 10) {
    stamps = Array.from({ length: 10 }, () => ({ stamped: false, angle: 0 }));
    character.death_stamps = stamps;
  }

  const totalStamped = stamps.filter(s => s.stamped).length;
  document.getElementById('stampCountBadge').textContent = `${totalStamped} / 10`;

  const grid = document.getElementById('stampGrid');
  grid.innerHTML = '';

  stamps.forEach((slot, idx) => {
    const cell = document.createElement('div');
    cell.onclick = () => toggleDeathStamp(idx);
    cell.className = `stamp-slot cursor-pointer h-20 rounded-xl border-2 border-dashed flex flex-col items-center justify-center relative select-none ${
      slot.stamped ? 'border-purple-500/90 bg-purple-950/30' : 'border-slate-700 bg-slate-950/60'
    }`;

    const numTag = `<span class="absolute top-1 left-1.5 text-[10px] font-bold text-slate-500">#${idx + 1}</span>`;
    if (slot.stamped) {
      cell.innerHTML = `
        ${numTag}
        <img src="logo.png" onerror="this.src='${POURCOON_STAMP_DATA_URI}'" class="pourcoon-stamp-img" style="transform: rotate(${slot.angle}deg); filter: invert(1) drop-shadow(0 0 6px rgba(168,85,247,0.8));" alt="Sello Pourcoon" />
      `;
    } else {
      cell.innerHTML = `${numTag}<span class="text-[10px] text-slate-600 font-semibold">Sellar</span>`;
    }
    grid.appendChild(cell);
  });
}

async function toggleDeathStamp(index) {
  const current = character.death_stamps[index];
  if (!current.stamped) {
    // Rotación aleatoria entre -30° y +30°
    const randomAngle = Math.floor(Math.random() * 61) - 30;
    character.death_stamps[index] = { stamped: true, angle: randomAngle };
  } else {
    character.death_stamps[index] = { stamped: false, angle: 0 };
  }

  const count = character.death_stamps.filter(s => s.stamped).length;
  renderStampCard();

  if (count === 10 && character.death_stamps[index].stamped) {
    triggerGruntBirthdayParty();
    await addCombatLog('¡Completó los 10 sellos de muerte del Pourcoon! ¡Grunt Birthday Party!');
  }

  await supabaseClient.from('characters').update({ death_stamps: character.death_stamps }).eq('id', character.id);
}

async function clearAllStamps() {
  character.death_stamps = Array.from({ length: 10 }, () => ({ stamped: false, angle: 0 }));
  renderStampCard();
  await supabaseClient.from('characters').update({ death_stamps: character.death_stamps }).eq('id', character.id);
}

function triggerGruntBirthdayParty() {
  confetti({ particleCount: 150, spread: 95, origin: { y: 0.6 } });
  setTimeout(() => confetti({ particleCount: 100, spread: 125, origin: { y: 0.5 } }), 320);

  const audioEl = document.getElementById('gruntAudio');
  if (audioEl) {
    audioEl.currentTime = 0;
    audioEl.play().catch(() => playPartySynthFallback());
  } else {
    playPartySynthFallback();
  }
}

function playPartySynthFallback() {
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const notes = [523.25, 659.25, 783.99, 1046.5];
  notes.forEach((freq, i) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(freq, ctx.currentTime + i * 0.09);
    gain.gain.setValueAtTime(0.25, ctx.currentTime + i * 0.09);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.09 + 0.35);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(ctx.currentTime + i * 0.09);
    osc.stop(ctx.currentTime + i * 0.09 + 0.35);
  });
}

// ============================================================================
// 5. ECONOMÍA DE ACCIÓN, CONJUROS Y ACOMPAÑANTES EN COMBATE
// ============================================================================
function renderActionEconomy() {
  const cs = character.combat_state || {};
  document.getElementById('roundCounter').textContent = `Asalto ${cs.round || 1}`;
  document.getElementById('concentrationBadge').textContent = cs.concentration_spell
    ? `Concentración: ${cs.concentration_spell}`
    : 'Concentración: Libre';
  document.getElementById('concentrationBadge').className = cs.concentration_spell
    ? 'text-[11px] px-2 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-700 font-bold'
    : 'text-[11px] px-2 py-0.5 rounded bg-slate-800 text-slate-400';

  const map = [
    { key: 'action_used', box: 'box-action', status: 'status-action', check: 'check-action' },
    { key: 'bonus_action_used', box: 'box-bonus', status: 'status-bonus', check: 'check-bonus' },
    { key: 'reaction_used', box: 'box-reaction', status: 'status-reaction', check: 'check-reaction' }
  ];

  map.forEach(item => {
    const used = Boolean(cs[item.key]);
    document.getElementById(item.box).className = `cursor-pointer rounded-xl p-3 border transition flex items-center justify-between ${
      used ? 'bg-slate-950/90 border-red-900/60 opacity-75' : 'bg-slate-900/70 border-slate-700 hover:border-purple-500'
    }`;
    document.getElementById(item.status).textContent = used ? 'Gastada' : 'Disponible';
    document.getElementById(item.status).className = `text-[11px] font-semibold ${used ? 'text-red-400' : 'text-emerald-400'}`;
    document.getElementById(item.check).className = `w-6 h-6 rounded-md border-2 flex items-center justify-center font-bold text-xs ${
      used ? 'bg-red-700 border-red-500 text-white' : 'border-slate-600 text-transparent'
    }`;
    document.getElementById(item.check).textContent = '✓';
  });

  document.getElementById('btn-hexcurse').className = `p-2.5 rounded-lg border text-left transition ${
    cs.hexblade_curse ? 'bg-purple-950/80 border-purple-500 ring-1 ring-purple-500' : 'bg-slate-900 border-slate-700'
  }`;
  document.getElementById('btn-shroud').className = `p-2.5 rounded-lg border text-left transition ${
    cs.necrotic_shroud_active ? 'bg-red-950/80 border-red-500 ring-1 ring-red-500' : 'bg-slate-900 border-slate-700'
  }`;
  document.getElementById('btn-shield').className = `p-2.5 rounded-lg border text-left transition ${
    cs.shield_active ? 'bg-cyan-950/80 border-cyan-400 ring-1 ring-cyan-400' : 'bg-slate-900 border-slate-700'
  }`;
}

async function toggleActionEconomy(key) {
  character.combat_state[key] = !character.combat_state[key];
  await saveCombatState();
}

async function toggleBuff(key) {
  character.combat_state[key] = !character.combat_state[key];
  if (key === 'hexblade_curse' && character.combat_state[key]) {
    character.combat_state.bonus_action_used = true;
    await addCombatLog('Activó Maldición del Filo Maléfico (Acción Adicional).');
  }
  if (key === 'necrotic_shroud_active' && character.combat_state[key]) {
    character.combat_state.action_used = true;
    await addCombatLog(`Activó Mortaja Necrótica (+${character.level} daño necrótico por turno).`);
  }
  await saveCombatState();
}

async function triggerReactionShield() {
  character.combat_state.shield_active = !character.combat_state.shield_active;
  if (character.combat_state.shield_active) {
    character.combat_state.reaction_used = true;
    await addCombatLog('Reacción: Lanzó Escudo (+5 a la CA hasta su próximo turno).');
  }
  await saveCombatState();
}

async function nextTurn() {
  character.combat_state.round = (character.combat_state.round || 1) + 1;
  character.combat_state.action_used = false;
  character.combat_state.bonus_action_used = false;
  character.combat_state.reaction_used = false;
  character.combat_state.shield_active = false;
  await addCombatLog(`--- Inicio del Asalto ${character.combat_state.round} ---`);
  await saveCombatState();
}

async function executeCastigoArcano() {
  const prog = getWarlockProgression(character.level);
  if ((character.spell_slots_used || 0) >= prog.slotCount) {
    alert('No te quedan espacios de Magia del Pacto disponibles. Realiza un Descanso Corto.');
    return;
  }
  character.spell_slots_used = (character.spell_slots_used || 0) + 1;
  await addCombatLog(`¡CASTIGO ARCANO! Gastó 1 espacio de Nvl ${prog.slotLevel} para sumar +${prog.smiteDice} de daño por Fuerza y DERRIBAR al objetivo.`);
  await saveCharacterCore();
}

function renderCombatSpells(prog, dc, atkBonus) {
  const container = document.getElementById('combatSpellsList');
  const activeSpells = spells.filter(s => s.is_equipped);

  if (activeSpells.length === 0) {
    container.innerHTML = `<div class="text-xs text-slate-500 p-4 border border-slate-800 rounded-xl">No hay conjuros marcados para combate. Actívalos en la Pestaña 3.</div>`;
    return;
  }

  container.innerHTML = activeSpells.map(sp => {
    const isCantrip = Number(sp.level) === 0;
    const levelBadge = isCantrip ? 'Truco' : `Nvl ${sp.level} (Lanza a Nvl ${Math.max(sp.level, prog.slotLevel)})`;
    return `
      <div class="bg-panel border border-slate-800 rounded-xl p-3 space-y-1.5 card-hover">
        <div class="flex items-start justify-between gap-2">
          <div>
            <div class="font-bold text-xs text-white flex items-center gap-1.5">
              <span>${sp.name}</span>
              ${sp.concentration ? `<span class="text-[10px] px-1.5 py-0.2 bg-amber-950 text-amber-300 rounded border border-amber-800">Conc.</span>` : ''}
            </div>
            <div class="text-[11px] text-slate-400">${levelBadge} • ${sp.casting_time} • ${sp.range_info}</div>
          </div>
          <button onclick="castSpellInCombat('${sp.id}')" class="px-2.5 py-1 rounded-lg bg-purple-800 hover:bg-purple-600 text-white text-[11px] font-bold shrink-0">
            Lanzar
          </button>
        </div>
        ${sp.damage_dice ? `<div class="text-xs font-bold text-purple-300">Efecto/Daño: ${sp.damage_dice} ${sp.damage_type || ''}</div>` : ''}
        <p class="text-[11px] text-slate-400 leading-relaxed">${sp.description || ''}</p>
      </div>
    `;
  }).join('');
}

async function castSpellInCombat(spellId) {
  const sp = spells.find(s => s.id === spellId);
  if (!sp) return;
  const prog = getWarlockProgression(character.level);

  if (Number(sp.level) > 0 && Number(sp.level) <= 5) {
    if ((character.spell_slots_used || 0) >= prog.slotCount) {
      if (!confirm('Tus espacios de pacto están agotados. ¿Lanzar gratis (ej. Dote Toque Feérico) o continuar de todos modos?')) return;
    } else {
      character.spell_slots_used = (character.spell_slots_used || 0) + 1;
    }
  }

  const time = (sp.casting_time || '').toLowerCase();
  if (time.includes('adicional')) character.combat_state.bonus_action_used = true;
  else if (time.includes('reacci')) character.combat_state.reaction_used = true;
  else character.combat_state.action_used = true;

  if (sp.concentration) {
    character.combat_state.concentration_spell = sp.name;
  }

  if (sp.name.toLowerCase().includes('agathys')) {
    character.hp_temp = prog.slotLevel * 5;
  }

  await addCombatLog(`Lanzó ${sp.name} (${sp.casting_time}${sp.concentration ? ' • Concentración' : ''}).`);
  await saveCharacterCore();
}

