function renderStatsGrid(prog) {
  const attrs = [
    { key: 'str', label: 'FUE', saveProf: false },
    { key: 'dex', label: 'DES', saveProf: false },
    { key: 'con', label: 'CON', saveProf: false },
    { key: 'int', label: 'INT', saveProf: false },
    { key: 'wis', label: 'SAB', saveProf: true },
    { key: 'cha', label: 'CAR', saveProf: true }
  ];
  document.getElementById('statsGrid').innerHTML = attrs.map(a => {
    const val = character[a.key] || 10;
    const mod = getMod(val);
    const save = mod + (a.saveProf ? prog.prof : 0);
    return `
      <div class="bg-slate-950 border border-slate-800 rounded-xl p-2">
        <div class="text-[10px] font-bold text-slate-400">${a.label}</div>
        <input type="number" value="${val}" onchange="updateAbility('${a.key}', this.value)" class="w-12 bg-transparent text-center font-black text-sm text-white focus:outline-none" />
        <div class="text-xs font-bold text-purple-400">${mod >= 0 ? `+${mod}` : mod}</div>
        <div class="text-[10px] text-slate-400 mt-0.5">Salv: <strong class="text-emerald-400">${save >= 0 ? `+${save}` : save}</strong></div>
      </div>
    `;
  }).join('');
}

async function updateAbility(key, val) {
  character[key] = Number(val);
  renderAll();
  await supabaseClient.from('characters').update({ [key]: character[key] }).eq('id', character.id);
}

async function updateLevel(newLevel) {
  character.level = Number(newLevel);
  await addCombatLog(`Lior Kurogane subió/ajustó a Nivel ${character.level}.`);
  await saveCharacterCore();
}

async function saveCharacterCore() {
  character.name = document.getElementById('charNameInput').value || 'Lior Kurogane';
  character.hp_current = Number(document.getElementById('hpCurrent').value);
  character.hp_max = Number(document.getElementById('hpMax').value);
  character.hp_temp = Number(document.getElementById('hpTemp').value);
  renderAll();
  await supabaseClient.from('characters').update({
    name: character.name,
    level: character.level,
    hp_current: character.hp_current,
    hp_max: character.hp_max,
    hp_temp: character.hp_temp,
    spell_slots_used: character.spell_slots_used,
    ammo_pistol: character.ammo_pistol,
    ammo_musket: character.ammo_musket,
    combat_state: character.combat_state
  }).eq('id', character.id);
}

async function saveCombatState() {
  renderAll();
  await supabaseClient.from('characters').update({ combat_state: character.combat_state }).eq('id', character.id);
}

async function toggleSpellSlot(idx) {
  const used = character.spell_slots_used || 0;
  character.spell_slots_used = (idx < used) ? idx : idx + 1;
  await saveCharacterCore();
}

async function shortRest() {
  character.spell_slots_used = 0;
  await addCombatLog('Descanso Corto: Espacios de Magia del Pacto restaurados.');
  await saveCharacterCore();
}

async function longRest() {
  character.hp_current = character.hp_max;
  character.hp_temp = 0;
  character.spell_slots_used = 0;
  character.combat_state = {
    round: 1,
    action_used: false,
    bonus_action_used: false,
    reaction_used: false,
    hexblade_curse: false,
    necrotic_shroud_active: false,
    necrotic_shroud_used: false,
    healing_hands_used: false,
    shield_active: false,
    concentration_spell: null
  };
  await addCombatLog('Descanso Largo: PG, Espacios de Pacto y rasgos raciales restaurados.');
  await saveCharacterCore();
}

async function useHealingHands() {
  character.hp_current = Math.min(character.hp_max, character.hp_current + character.level);
  character.combat_state.action_used = true;
  await addCombatLog(`Manos Curativas: Recuperó +${character.level} PG.`);
  await saveCharacterCore();
}

async function saveCurrency() {
  character.currency = {
    cp: Number(document.getElementById('coin-cp').value),
    sp: Number(document.getElementById('coin-sp').value),
    ep: Number(document.getElementById('coin-ep').value),
    gp: Number(document.getElementById('coin-gp').value),
    pp: Number(document.getElementById('coin-pp').value)
  };
  await supabaseClient.from('characters').update({ currency: character.currency }).eq('id', character.id);
}

async function toggleInventoryFlag(id, field, checked) {
  const item = inventory.find(i => i.id === id);
  if (item) item[field] = checked;
  renderAll();
  await supabaseClient.from('character_inventory').update({ [field]: checked }).eq('id', id);
}

async function toggleEquipSpell(id, checked) {
  const sp = spells.find(s => s.id === id);
  if (sp) sp.is_equipped = checked;
  renderAll();
  await supabaseClient.from('character_spells').update({ is_equipped: checked }).eq('id', id);
}

async function toggleSummonCompanion(id, checked) {
  const comp = companions.find(c => c.id === id);
  if (comp) comp.is_summoned = checked;
  renderAll();
  await supabaseClient.from('character_companions').update({ is_summoned: checked }).eq('id', id);
}

async function updateCompanionHP(id, hp) {
  const comp = companions.find(c => c.id === id);
  if (comp) comp.hp_current = Number(hp);
  await supabaseClient.from('character_companions').update({ hp_current: Number(hp) }).eq('id', id);
}

// ============================================================================
// 8. BITÁCORA Y MODALES DE EDICIÓN/CREACIÓN
// ============================================================================
function renderCombatLogs() {
  const container = document.getElementById('combatLogList');
  if (logs.length === 0) {
    container.innerHTML = `<div class="text-slate-500">Sin acciones registradas en este encuentro.</div>`;
    return;
  }
  container.innerHTML = logs.map(l => `
    <div class="p-2 rounded bg-slate-950/90 border border-slate-800/80 text-slate-300">
      <span class="text-purple-400 font-bold">[A${l.round_num || 1}]</span> ${l.log_text}
    </div>
  `).join('');
}

async function addCombatLog(text) {
  const roundNum = character?.combat_state?.round || 1;
  const newEntry = { character_id: character.id, round_num: roundNum, log_text: text };
  logs.unshift(newEntry);
  renderCombatLogs();
  await supabaseClient.from('combat_logs').insert([newEntry]);
}

async function clearCombatLogs() {
  logs = [];
  renderCombatLogs();
  await supabaseClient.from('combat_logs').delete().eq('character_id', character.id);
}

function switchTab(tabName) {
  ['combat', 'equipment', 'spells', 'companions'].forEach(t => {
    document.getElementById(`tab-${t}`).classList.toggle('hidden', t !== tabName);
    const btn = document.getElementById(`tabBtn-${t}`);
    if (t === tabName) {
      btn.className = 'px-4 py-1.5 rounded-lg text-sm font-bold bg-purple-700 text-white shadow flex items-center gap-2';
    } else {
      btn.className = 'px-4 py-1.5 rounded-lg text-sm font-semibold text-slate-400 hover:text-white hover:bg-slate-800/60 flex items-center gap-2';
    }
  });
}

function closeModal() {
  document.getElementById('editorModal').classList.add('hidden');
}

function openItemModal(id = null) {
  const item = inventory.find(i => i.id === id) || {
    name: '', category: 'arma', subcategory: 'Arma Marcial', damage_dice: '1d8', damage_type: 'Perforante',
    range_info: 'Cuerpo a cuerpo', properties: '', ac_bonus: 0, magic_bonus: 1,
    is_favorite_pact: false, is_pact_weapon: true, is_equipped: true
  };
  document.getElementById('modalTitle').textContent = id ? 'Editar Arma / Equipo' : 'Crear Arma / Equipo';
  document.getElementById('modalBody').innerHTML = `
    <div class="grid grid-cols-2 gap-3">
      <div class="col-span-2"><label class="text-slate-400">Nombre</label><input id="m-item-name" value="${item.name}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
      <div><label class="text-slate-400">Categoría</label>
        <select id="m-item-cat" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white">
          <option value="arma" ${item.category === 'arma' ? 'selected' : ''}>Arma</option>
          <option value="armadura" ${item.category === 'armadura' ? 'selected' : ''}>Armadura</option>
          <option value="escudo" ${item.category === 'escudo' ? 'selected' : ''}>Escudo</option>
          <option value="objeto" ${item.category === 'objeto' ? 'selected' : ''}>Objeto / Consumible</option>
          <option value="herramienta" ${item.category === 'herramienta' ? 'selected' : ''}>Herramienta</option>
        </select>
      </div>
      <div><label class="text-slate-400">Subcategoría</label><input id="m-item-subcat" value="${item.subcategory || ''}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
      <div><label class="text-slate-400">Dados de Daño (ej. 1d10)</label><input id="m-item-dice" value="${item.damage_dice || ''}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
      <div><label class="text-slate-400">Tipo de Daño</label><input id="m-item-dtype" value="${item.damage_type || ''}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
      <div><label class="text-slate-400">Bono Mágico (+0, +1, +2)</label><input id="m-item-magic" type="number" value="${item.magic_bonus || 0}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
      <div><label class="text-slate-400">CA Base / Bono Escudo</label><input id="m-item-ac" type="number" value="${item.ac_bonus || 0}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
      <div class="col-span-2"><label class="text-slate-400">Alcance</label><input id="m-item-range" value="${item.range_info || ''}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
      <div class="col-span-2"><label class="text-slate-400">Propiedades</label><input id="m-item-props" value="${item.properties || ''}" class="w-full mt-1 bg-slate-900 border border-slate-700 rounded p-2 text-white" /></div>
    </div>
  `;
  document.getElementById('modalSaveBtn').onclick = async () => {
    const payload = {
      character_id: character.id,
      name: document.getElementById('m-item-name').value,
      category: document.getElementById('m-item-cat').value,
      subcategory: document.getElementById('m-item-subcat').value,
      damage_dice: document.getElementById('m-item-dice').value || null,
      damage_type: document.getElementById('m-item-dtype').value || null,
      magic_bonus: Number(document.getElementById('m-item-magic').value),
      ac_bonus: Number(document.getElementById('m-item-ac').value),
      range_info: document.getElementById('m-item-range').value,
      properties: document.getElementById('m-item-props').value,
      is_favorite_pact: item.is_favorite_pact,
      is_pact_weapon: item.is_pact_weapon,
      is_equipped: item.is_equipped
    };
    if (id) await supabaseClient.from('character_inventory').update(payload).eq('id', id);
    else await supabaseClient.from('character_inventory').insert([payload]);
    closeModal();
    initApp();
  };
  document.getElementById('editorModal').classList.remove('hidden');
}

async function deleteItem(id) {
  if (!confirm('¿Eliminar este elemento del inventario?')) return;
  await supabaseClient.from('character_inventory').delete().eq('id', id);
  initApp();
}

